export template<static gap: Length = 12px>
layout Reading<4ui, 2ui> {
    width: fill;
    height: fit;
    column root { gap: gap; slot body { height: fit; } }
}

import { Reading as ImportedReading } from "./Reading";
import { createElement } from "react";
layout Page = instantiate ImportedReading<gap: 8px> with { root.padding: 16px; };
export function Main(): ReactNode {
    stream Content { body: <p>Template content</p>; }
    return bind Page using Content;
}

